def alphabeta_visits(node):

    def max_value(subtree, alpha, beta):
        if subtree.is_leaf():
            return subtree.value, 1
        value, visits = float('-inf'), 1
        for child in subtree.children:
            v, n = min_value(child, alpha, beta)
            visits += n
            value = max(value, v)
            alpha = max(alpha, value)
