def negamax(node, alpha, beta, color):
    if node.is_leaf():
        return color * node.value
    value = float('-inf')
    for child in node.children:
        v = -negamax(child, -beta, -alpha, -color)
        value = max(value, v)
        alpha = max(alpha, value)
        if value >= beta:
            return value
    return value

